\title{The Modular Obstruction for Sums of Three Cubes: \\ A Complete Local Characterization and the Density Conjecture}
\author{Aristotle}
\date{2026-06-30}

\begin{document}

\begin{abstract}
We study the classical Diophantine problem of representing an integer $n$ as a sum of three integer cubes, $x^3 + y^3 + z^3 = n$, with $x, y, z \in \mathbb{Z}$ unrestricted in sign. We give a complete and rigorous treatment of the only known local obstruction: an integer congruent to $4$ or $5$ modulo $9$ admits no representation. We prove this from first principles by showing that every integer cube lies in $\{0,1,8\}$ modulo $9$ and that no sum of three such residues equals $4$ or $5$ modulo $9$. We situate the obstruction within the conjectural framework of Heath-Brown, which asserts that congruence to $4$ or $5$ modulo $9$ is the only obstruction, and we make explicit which direction of the resulting characterization is a theorem and which is open. We connect the problem to the geometry of cubic surfaces, the symmetry $n \mapsto -n$, one-parameter polynomial families of representations, and the Hasse principle, and we provide explicit witnesses for all admissible residue classes.
\end{abstract}

\maketitle

\section{Introduction}

The equation
\[
x^3 + y^3 + z^3 = n, \qquad x, y, z \in \mathbb{Z},
\]
asks which integers $n$ are sums of three signed integer cubes. Because cubes may be negative, the search space is unbounded: a single $n$ may require coordinates that are enormous and nearly cancel. For instance,
\[
30 = 2{,}220{,}422{,}932^3 + (-2{,}218{,}888{,}517)^3 + (-283{,}059{,}965)^3,
\]
and the cases $33$ and $42$ were resolved in $2019$ only after large distributed computations. The problem splits into two parts of different logical status: an \emph{obstruction} (some integers are provably not sums of three cubes), which is fully settled, and a \emph{sufficiency} statement (all remaining integers are), which is the open conjecture of Heath-Brown. We give a self-contained account of the obstruction and a careful logical analysis of the characterization.

\subsection{Notation}
We write $\mathbb{Z}/9\mathbb{Z}$ for residues modulo $9$ and $\bar a$ for the image of $a \in \mathbb{Z}$.

\begin{definition}[Sum of three cubes]
An integer $n$ is a \emph{sum of three cubes}, written $S(n)$, if there exist $x,y,z \in \mathbb{Z}$ with $x^3 + y^3 + z^3 = n$.
\end{definition}

\section{Cubic residues modulo nine}

\begin{lemma}[Cubic residues mod 9]\label{lem:cubes}
For every integer $x$, $\ \overline{x^3} \in \{\bar 0, \bar 1, \bar 8\} \subseteq \mathbb{Z}/9\mathbb{Z}$.
\end{lemma}

\begin{proof}
The value $\overline{x^3}$ depends only on $\bar x$, so it suffices to check the nine residues:
\[
\begin{aligned}
0^3 &\equiv 0, & 1^3 &\equiv 1, & 2^3 = 8 &\equiv 8,\\
3^3 = 27 &\equiv 0, & 4^3 = 64 &\equiv 1, & 5^3 = 125 &\equiv 8,\\
6^3 = 216 &\equiv 0, & 7^3 = 343 &\equiv 1, & 8^3 = 512 &\equiv 8.
\end{aligned}
\]
Each lies in $\{0,1,8\}$. Equivalently, a cube modulo $9$ records only the base modulo $3$, mapped to $\{0,1,-1\}$.
\end{proof}

\section{The modular obstruction}

\begin{lemma}[No triple sum hits 4 or 5]\label{lem:sum}
For all $a,b,c \in \{\bar 0, \bar 1, \bar 8\}$, $\ a+b+c \neq \bar 4$ and $a+b+c \neq \bar 5$.
\end{lemma}

\begin{proof}
A finite check over the $27$ ordered triples. Identifying $\bar 8 = -\bar 1$, the attainable sums are $\{-3,\dots,3\} \pmod 9 = \{\bar0,\bar1,\bar2,\bar3,\bar6,\bar7,\bar8\}$, which omits $\bar 4$ and $\bar 5$.
\end{proof}

\begin{theorem}[Modular obstruction]\label{thm:obstruction}
If $\bar n \in \{\bar 4, \bar 5\}$ then $n$ is not a sum of three cubes.
\end{theorem}

\begin{proof}
If $x^3+y^3+z^3 = n$, reduce modulo $9$: by Lemma~\ref{lem:cubes} each $\overline{x^3},\overline{y^3},\overline{z^3} \in \{\bar0,\bar1,\bar8\}$, so by Lemma~\ref{lem:sum} their sum is not $\bar4$ or $\bar5$, contradicting $\bar n \in \{\bar4,\bar5\}$.
\end{proof}

This excludes exactly the integers $n \equiv \pm 4 \pmod 9$.

\section{Symmetry}

\begin{proposition}[Negation symmetry]\label{prop:neg}
For every integer $n$, $S(n)$ holds iff $S(-n)$ holds.
\end{proposition}

\begin{proof}
If $x^3+y^3+z^3 = n$ then $(-x)^3+(-y)^3+(-z)^3 = -n$, and conversely.
\end{proof}

The excluded classes $\bar4$ and $\bar5 = -\bar4$ are swapped by negation, consistent with the surface's central symmetry.

\section{Explicit witnesses}

\begin{proposition}[Small witnesses]\label{prop:witnesses}
\[
\begin{aligned}
0 &= 0^3 + 0^3 + 0^3, & 1 &= 1^3 + 0^3 + 0^3, & 2 &= 1^3 + 1^3 + 0^3,\\
3 &= 1^3 + 1^3 + 1^3, & 6 &= 2^3 + (-1)^3 + (-1)^3, & 7 &= 2^3 + 0^3 + (-1)^3,\\
8 &= 2^3 + 0^3 + 0^3. &&&&
\end{aligned}
\]
\end{proposition}

These cover all admissible residues $\{0,1,2,3,6,7,8\}$ modulo $9$, confirming no class outside $\{4,5\}$ is locally obstructed.

\section{Characterization and the Heath-Brown conjecture}

\begin{conjecture}[Heath-Brown sufficiency]\label{conj:hb}
Every integer $n$ with $\bar n \notin \{\bar4,\bar5\}$ is a sum of three cubes.
\end{conjecture}

This is not reducible to a finite computation: each admissible residue class contains infinitely many integers (e.g.\ $0,9,18,\dots$), which may require arbitrarily large representations.

\begin{theorem}[Complete characterization, one direction conjectural]\label{thm:char}
For every integer $n$, $\ \neg S(n) \iff \bar n \in \{\bar4,\bar5\}$. The implication $(\Leftarrow)$ is the proven Theorem~\ref{thm:obstruction}; the implication $(\Rightarrow)$ is, by contraposition, exactly Conjecture~\ref{conj:hb}, and is open.
\end{theorem}

\begin{proof}
$(\Leftarrow)$ is Theorem~\ref{thm:obstruction}. $(\Rightarrow)$ contraposes to $\bar n \notin \{\bar4,\bar5\} \Rightarrow S(n)$, which is Conjecture~\ref{conj:hb}.
\end{proof}

Every integer below $100$ has been verified, including the difficult cases $33$ and $42$ (resolved $2019$), yet the conjecture remains unproven.

\section{Geometry and the Hasse principle}

For $n \neq 0$ the real solutions of $x^3+y^3+z^3 = n$ form a smooth cubic surface in $\mathbb{R}^3$; representability asks for an integer point on it. The Hasse principle asks whether solvability in all completions of $\mathbb{Q}$ implies solvability over $\mathbb{Q}$. Here the surface always has real points, and the only congruence obstruction is the one modulo $9$ of Theorem~\ref{thm:obstruction}. Conjecture~\ref{conj:hb} asserts that local solvability suffices for integral solvability: nine is the whole story. The extreme size of minimal solutions is consistent with heuristic lattice-point counts.

\section{Polynomial families}

Some values admit one-parameter polynomial families of representations. For example, Mahler's identity
\[
(9t^4)^3 + (3t - 9t^4)^3 + (1 - 9t^3)^3 = 1
\]
gives infinitely many representations of $1$. Such families, together with the negation symmetry of Proposition~\ref{prop:neg}, structure the study of representation densities and motivate the conjecture that multiply-represented values lie on algebraic curves within the surface.

\section{Algorithms}

\textbf{Local obstruction test.} Compute $r = n \bmod 9$; if $r \in \{4,5\}$ output ``not representable'' (Theorem~\ref{thm:obstruction}), else ``no local obstruction''. Cost $O(1)$.

\textbf{Bounded witness search.} For $|x|,|y|,|z| \le B$, fix $x,z$ and test whether $n - x^3 - z^3$ is a perfect cube; Proposition~\ref{prop:neg} halves the work. Cost $O(B^2 \log B)$ per target. This finds the small witnesses instantly but cannot reach hard targets like $33$.

\section{Discussion and future directions}

The negative side (impossibility) is elementary and complete; the positive side (possibility) is conjectural, computationally savage, and tied to Diophantine geometry. Future directions include: proving Conjecture~\ref{conj:hb} (``nine is the whole story''); exhibiting one-parameter families for every multiply-represented value; showing the number of representations with coordinates bounded by $T$ tends to infinity for every admissible $n$; and establishing that minimal witnesses for hard values are asymptotically balanced.

\section{Conclusion}

We proved that no integer congruent to $4$ or $5$ modulo $9$ is a sum of three cubes, gave witnesses for every admissible residue class, recorded the negation symmetry, and assembled a precise characterization whose only open direction is Heath-Brown's density conjecture.

