from typing import Set

def cubic_residues_mod9() -> Set[int]:
    """Return the set of values x^3 mod 9 over all residues x mod 9."""
    return {(x ** 3) % 9 for x in range(9)}

def attainable_triple_sums_mod9() -> Set[int]:
    """Residues mod 9 expressible as a sum of three cubes mod 9."""
    r = cubic_residues_mod9()
    return {(a + b + c) % 9 for a in r for b in r for c in r}

if __name__ == "__main__":
    print("cube residues mod 9:", sorted(cubic_residues_mod9()))
    sums = attainable_triple_sums_mod9()
    print("attainable triple sums:", sorted(sums))
    print("missing (obstructed):", sorted(set(range(9)) - sums))
    assert 4 not in sums and 5 not in sums
    print("Proven: n = 4 or 5 mod 9 is never a sum of three cubes.")

